import { expect, test, uniqueName } from "../../fixtures";

test("updating a draft vendor's contact email returns 200 and records vendor.updated", { tag: "@VEN-08" }, async ({ apiAs }) => {
  const member = await apiAs("member");

  const create = await member.post("/api/vendors", {
    data: { name: uniqueName("Acme Freight"), category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  expect(create.status(), await create.text()).toBe(201);
  const vendor = await create.json();
  expect(vendor.status, JSON.stringify(vendor)).toBe("draft");

  const res = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });
  expect(res.status(), await res.text()).toBe(200);
  const updated = await res.json();
  expect(updated.contact_email, JSON.stringify(updated)).toBe("billing@acmefreight.example");

  await expect
    .poll(
      async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = (await audit.json()) as { items: { action: string }[] };
        return body.items.map((e) => e.action);
      },
      { message: "audit event vendor.updated recorded" },
    )
    .toContain("vendor.updated");
});
